changeSet.sql:
CREATE TABLE ai_workflow_analyses ( id SERIAL PRIMARY KEY, team_id INTEGER NOT NULL REFERENCES teams(id) ON DELETE CASCADE, team_repository_id INTEGER NOT NULL REFERENCES team_repositories(id) ON DELETE CASCADE, commit_sha TEXT, status TEXT NOT NULL DEFAULT 'running' CHECK (status IN ('queued', 'running', 'succeeded', 'failed')), source TEXT NOT NULL DEFAULT 'heuristic' CHECK (source IN ('heuristic', 'agent')), agent_session_id INTEGER, error TEXT, started_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, finished_at TIMESTAMPTZ ); CREATE INDEX idx_ai_workflow_analyses_team ON ai_workflow_analyses(team_id, finished_at DESC NULLS LAST); CREATE INDEX idx_ai_workflow_analyses_repo ON ai_workflow_analyses(team_repository_id, finished_at DESC NULLS LAST);
CREATE TABLE ai_workflows ( id SERIAL PRIMARY KEY, analysis_id INTEGER NOT NULL REFERENCES ai_workflow_analyses(id) ON DELETE CASCADE, name TEXT NOT NULL, trigger_summary TEXT, diagram_mermaid TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 0 ); CREATE INDEX idx_ai_workflows_analysis ON ai_workflows(analysis_id, sort_order);
CREATE TABLE ai_llm_call_recommendations ( id SERIAL PRIMARY KEY, analysis_id INTEGER NOT NULL REFERENCES ai_workflow_analyses(id) ON DELETE CASCADE, workflow_id INTEGER REFERENCES ai_workflows(id) ON DELETE CASCADE, team_id INTEGER NOT NULL REFERENCES teams(id) ON DELETE CASCADE, file_path TEXT NOT NULL, start_line INTEGER, end_line INTEGER, code_url TEXT, detected_model TEXT, api_key_id INTEGER REFERENCES api_keys(id) ON DELETE SET NULL, recommended_sla TEXT NOT NULL CHECK (recommended_sla IN ('ux-critical', 'ux-high-prio', 'ux-background')), confidence REAL NOT NULL DEFAULT 0.5, justification TEXT NOT NULL DEFAULT '', traffic_flags JSONB, review_status TEXT NOT NULL DEFAULT 'pending' CHECK (review_status IN ('pending', 'accepted', 'overridden', 'rejected')), confirmed_sla TEXT CHECK (confirmed_sla IS NULL OR confirmed_sla IN ('ux-critical', 'ux-high-prio', 'ux-background')), reviewed_by INTEGER REFERENCES users(id) ON DELETE SET NULL, reviewed_at TIMESTAMPTZ ); CREATE INDEX idx_ai_llm_recs_team_status ON ai_llm_call_recommendations(team_id, review_status); CREATE INDEX idx_ai_llm_recs_analysis ON ai_llm_call_recommendations(analysis_id);

rollback.sql:
DROP TABLE IF EXISTS ai_llm_call_recommendations;
DROP TABLE IF EXISTS ai_workflows;
DROP TABLE IF EXISTS ai_workflow_analyses;
